'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');
const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { createTeamBridge } = require('../server/team-bridge');

// Verbatim synthetic replies generated by usage_summary_mcp.rs against the real
// awr-server binary and its PostgreSQL fixture.
function sample(name) {
  return JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', `usage-summary-web-${name}.json`), 'utf8'));
}
const AUDIT = sample('audit');
const SELF = sample('self');
const UNCOLLECTED = sample('uncollected');
const FIXTURE_DIR = path.resolve(__dirname, '../../../tests/fixtures/workstreams/team-web-loop');

async function startUpstream(handler) {
  const server = http.createServer(handler);
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return {
    base: `http://127.0.0.1:${server.address().port}`,
    close: () => new Promise((resolve) => {
      server.close(resolve);
      server.closeAllConnections();
    }),
  };
}

async function startBridge(teamUrl, now) {
  const bridge = createTeamBridge({ teamUrl, teamFixtureDir: FIXTURE_DIR, port: 0, now });
  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, 'http://127.0.0.1');
    const handler = bridge.routes[`${req.method} ${url.pathname}`];
    if (!handler) {
      res.writeHead(404, { 'content-type': 'application/json' });
      res.end('{}');
      return;
    }
    let body = null;
    if (req.method === 'POST') {
      const chunks = [];
      for await (const chunk of req) chunks.push(chunk);
      const raw = Buffer.concat(chunks).toString('utf8');
      body = raw ? JSON.parse(raw) : {};
    }
    const json = await handler(url, body, req, res);
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify(json));
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  return {
    base: `http://127.0.0.1:${server.address().port}`,
    bridge,
    close: () => new Promise((resolve) => {
      server.close(resolve);
      server.closeAllConnections();
    }),
  };
}

function jsonReply(response, body, status = 200) {
  response.writeHead(status, { 'content-type': 'application/json' });
  response.end(JSON.stringify(body));
}

function collectBody(request, callback) {
  const chunks = [];
  request.on('data', (chunk) => chunks.push(chunk));
  request.on('end', () => callback(JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}')));
}

test('usage bridge serves verbatim real-service audit, self and uncollected replies and rejects invalid selectors', async () => {
  const calls = [];
  const upstream = await startUpstream((request, response) => {
    if (request.url === '/v1/web/projects/one/query' && request.method === 'POST') {
      collectBody(request, (body) => {
        calls.push({ url: request.url, body, cookie: request.headers.cookie });
        const cookie = request.headers.cookie || '';
        if (cookie.includes('ws_self')) {
          if (body.member_actor_id && body.member_actor_id !== 'peer-dev') {
            jsonReply(response, { code: 'Forbidden', message: 'access denied' }, 403);
            return;
          }
          jsonReply(response, SELF);
          return;
        }
        if (cookie.includes('ws_uncollected')) {
          jsonReply(response, UNCOLLECTED);
          return;
        }
        jsonReply(response, AUDIT);
      });
      return;
    }
    jsonReply(response, { code: 'NotFound' }, 404);
  });
  const now = AUDIT.data.as_of.at_unix_ms + 1000;
  const { base, bridge, close } = await startBridge(upstream.base, () => now);
  try {
    // Strictly read-only: no POST/PUT/DELETE route at /api/team/usage.
    for (const method of ['POST', 'PUT', 'PATCH', 'DELETE']) {
      assert.equal(bridge.routes[`${method} /api/team/usage`], undefined);
    }

    const auditRes = await (await fetch(`${base}/api/team/usage?project=one`, {
      headers: { cookie: 'awr_web_session=ws_audit' },
    })).json();
    assert.equal(auditRes.ok, true);
    assert.deepEqual(auditRes.result, AUDIT);
    assert.equal(auditRes.result.data.coverage.status, 'partial');
    assert.deepEqual(
      auditRes.result.data.coverage.groups.missing.map((g) => g.name),
      ['Delivery Group', 'Platform Group'],
    );
    assert.equal(auditRes.result.data.project.cost.status, 'not_collected');
    assert.equal(auditRes.result.data.project.cost.amount_micros, null);

    const selfRes = await (await fetch(`${base}/api/team/usage?project=one`, {
      headers: { cookie: 'awr_web_session=ws_self' },
    })).json();
    assert.equal(selfRes.ok, true);
    assert.deepEqual(selfRes.result, SELF);
    assert.equal(selfRes.result.data.member_scope, 'self');
    assert.equal(selfRes.result.data.by_member.length, 1);

    // Non-audit member requesting another member is refused with Forbidden.
    const forbidden = await (await fetch(`${base}/api/team/usage?project=one&member_actor_id=agent`, {
      headers: { cookie: 'awr_web_session=ws_self' },
    })).json();
    assert.equal(forbidden.ok, false);
    assert.equal(forbidden.error.code, 'Forbidden');
    assert.equal(forbidden.result, undefined);

    const uncollectedRes = await (await fetch(`${base}/api/team/usage?project=one`, {
      headers: { cookie: 'awr_web_session=ws_uncollected' },
    })).json();
    assert.equal(uncollectedRes.ok, true);
    assert.deepEqual(uncollectedRes.result, UNCOLLECTED);
    assert.equal(uncollectedRes.result.data.project.duration.status, 'not_collected');
    assert.equal(uncollectedRes.result.data.project.duration.summed_ms, null);
    assert.equal(uncollectedRes.result.data.project.tokens.input_tokens, null);

    // Invalid selectors (including personal-ranking attempts) are rejected before reaching upstream.
    const beforeInvalid = calls.length;
    for (const pathname of [
      '/api/team/usage',
      '/api/team/usage?project=one&sort_by=tokens_desc',
      '/api/team/usage?project=one&rank=1',
      '/api/team/usage?project=one&session_id=s1',
      '/api/team/usage?project=one&limit=10',
      '/api/team/usage?project=one&cursor=abc',
      '/api/team/usage?project=one&project=two',
    ]) {
      const invalid = await (await fetch(`${base}${pathname}`, {
        headers: { cookie: 'awr_web_session=ws_audit' },
      })).json();
      assert.equal(invalid.ok, false, pathname);
      assert.equal(invalid.error.code, 'InvalidInput', pathname);
      assert.equal(invalid.result, undefined, pathname);
    }
    assert.equal(calls.length, beforeInvalid, 'invalid selectors must never reach upstream');
  } finally {
    await close();
    await upstream.close();
  }
});

test('usage bridge refuses replies that turn not_collected into zero or introduce personal ranking', async () => {
  let reply = AUDIT;
  const upstream = await startUpstream((request, response) => {
    collectBody(request, () => jsonReply(response, reply));
  });
  const { base, close } = await startBridge(upstream.base, () => AUDIT.data.as_of.at_unix_ms + 1000);
  try {
    const cases = [
      ['not_collected duration turned into zero', UNCOLLECTED, (v) => { v.data.project.duration.summed_ms = 0; }],
      ['not_collected tokens turned into zero', UNCOLLECTED, (v) => { v.data.project.tokens.input_tokens = 0; }],
      ['not_collected cost turned into zero', AUDIT, (v) => { v.data.project.cost.amount_micros = 0; }],
      ['personal comparison ranking enabled', AUDIT, (v) => { v.data.personal_comparison_ranking = true; }],
      ['member ordering changed from identifier_asc', AUDIT, (v) => { v.data.member_ordering = 'tokens_desc'; }],
      ['member row carries rank field', AUDIT, (v) => { v.data.by_member[0].rank = 1; }],
      ['by_member sorted out of ascending identifier order', AUDIT, (v) => { v.data.by_member.reverse(); }],
      ['execution_authorized forged true', AUDIT, (v) => { v.data.execution_authorized = true; }],
    ];
    for (const [label, seed, mutate] of cases) {
      reply = structuredClone(seed);
      mutate(reply);
      const res = await (await fetch(`${base}/api/team/usage?project=one`, {
        headers: { cookie: 'awr_web_session=ws_audit' },
      })).json();
      assert.equal(res.ok, false, label);
      assert.equal(res.error.code, 'BadGateway', label);
      assert.equal(res.result, undefined, label);
    }
  } finally {
    await close();
    await upstream.close();
  }
});

test('usage fixtures contain no credentials or private prose and demo bridge serves valid usage.summary', async () => {
  for (const fixture of [AUDIT, SELF, UNCOLLECTED]) {
    const text = JSON.stringify(fixture).toLowerCase();
    for (const banned of ['secret', 'password', 'bearer', 'awr1.']) {
      assert.ok(!text.includes(banned), `${banned} leaked in fixture`);
    }
  }
  const bridge = createTeamBridge({ demo: true, port: 0, demoVariant: 'canonical', demoTimestampShiftMs: 0 });
  const reply = await bridge.routes['GET /api/team/usage'](
    new URL('http://127.0.0.1/api/team/usage?project=P-001'),
    null,
    { headers: {}, method: 'GET' },
    { setHeader() {} },
  );
  assert.equal(reply.ok, true);
  assert.equal(reply.result.data.project.cost.status, 'not_collected');
  assert.equal(reply.result.data.personal_comparison_ranking, false);
});
